		\begin{itemchoice}
			\itemch Ta có $P(B)=0{,}6$. Do đó ý này đúng.
			\itemch Ta có $P\left(A \mid \overline{B}\right)=0{,}4$. Do đó ý này sai.
			\itemch Xác suất gặp bệnh án của bệnh nhân bị biến chứng là $\displaystyle P(A) = 0{,}6 \cdot 0{,}2 + 0{,}4 \cdot 0{,}4 = 0{,}28 = 28\%$. Do đó ý này sai.
			\itemch Biết bệnh án rút ra là của bệnh nhân bị biến chứng, xác suất bệnh nhân bị bỏng nhiệt là $\displaystyle P(B \mid A) = \frac{P(A \mid B) \cdot P(B)}{P(A)} = \frac{0{,}6 \cdot 0{,}2}{0{,}28} = \frac{3}{7}$. Do đó ý này sai.
		\end{itemchoice}

\begin{itemchoice}
			\itemch Hàm số xác định khi $x-1 \neq 0 \Leftrightarrow x \neq 1$. Tập xác định là $D=\mathbb{R} \setminus \{1\}$. Do đó ý này sai.
			\itemch Đồ thị hàm số $y=f(x)$ có tiệm cận đứng là đường thẳng $x=1$. Do đó ý này đúng.
			\itemch Hàm số $\displaystyle f(x)=\frac{x^2+3}{x-1}=x+1+\frac{4}{x-1}$. Đồ thị hàm số $y=f(x)$ có tiệm cận xiên là đường thẳng $y=x+1$. Do đó ý này sai.
			\itemch Đồ thị hàm số $y=f(x)$ có tiệm cận đứng là đường thẳng $x=1$, tiệm cận xiên là đường thẳng $y=x+1$ nên tâm đối xứng là $A(1; 2) \Rightarrow x_0+y_0=1+2=3$. Do đó ý này đúng.
		\end{itemchoice}

\begin{itemchoice}
			\itemch Đường thẳng $d \colon y = ax+b$ đi qua hai điểm $A(1;3), B(5;7)$ nên $\begin{cases} a+b=3 \\ 5a+b=7 \end{cases} \Rightarrow \begin{cases} a=1 \\ b=2 \end{cases}$. Vậy đường thẳng $d \colon y = x+2$. Ta có: $\displaystyle \int_1^5 g(x)\,dx = \int_1^5 (x+2)\,dx = \left( \frac{x^2}{2} + 2x \right) \bigg|_1^5 = \left( \frac{25}{2} + 10 \right) - \left( \frac{1}{2} + 2 \right) = 20$. Do đó ý này đúng.
			\itemch Ta có $g'(x) = 1$. Khi đó: $\displaystyle \int_1^5 [3g'(x)-1]\,dx = \int_1^5 2\,dx = 2x \big|_1^5 = 10 - 2 = 8$. Do đó ý này sai.
			\itemch Hình phẳng giới hạn bởi đồ thị $(P)$ và đường thẳng $d$ có diện tích là $\displaystyle S = \frac{32}{3}$ hay $\displaystyle \int_1^5 [g(x) - f(x)]\,dx = \frac{32}{3} \Leftrightarrow \int_1^5 g(x)\,dx - \int_1^5 f(x)\,dx = \frac{32}{3} \Rightarrow \int_1^5 f(x)\,dx = \int_1^5 g(x)\,dx - \frac{32}{3} = 20 - \frac{32}{3} = \frac{28}{3}$. Do đó ý này sai.
			\itemch Hình phẳng giới hạn bởi đồ thị $(P)$ và các đường thẳng $y=7, x=1, x=5$ có diện tích là $\displaystyle S = \int_1^5 [7 - f(x)]\,dx = \int_1^5 7\,dx - \int_1^5 f(x)\,dx = 7x \big|_1^5 - \frac{28}{3} = 35 - 7 - \frac{28}{3} = \frac{56}{3}$. Do đó ý này sai.
		\end{itemchoice}
